import { describe, expect, it } from 'vitest';
import {
  targetFlowDiagram,
  triggerActor,
} from '../../../../src/domain/diagrams/target-flow-diagram.js';
import type { MappedFlow } from '../../../../src/domain/planning/target-flows.js';
import { mappedFlow } from '../../../support/flow-fixtures.js';
import { fakeOpenAiKey } from '../../../support/secret-fixture.js';

// RF-625, RF-508, ADR-013: the sequence diagram of a target flow is generated by code from the
// checked flow. Participant ids are generated, every label is coded, secrets are masked first and
// a step mapped to no component is drawn marked.

const keep = (text: string): string => text;

function stepOf(number: number, component: string | null, action: string) {
  return {
    ...{ claimId: `FLOW-001.c${String(number)}`, text: `Legacy step ${String(number)}.` },
    ...{ touches: null, component, action, files: [], inferred: false },
  };
}

const flow: MappedFlow = {
  ...{ cardId: 'FLOW-001', title: 'Place an order' },
  trigger: 'The customer presses Pay.',
  outcome: 'The order is stored.',
  steps: [
    stepOf(1, 'Web', 'Sends it.'),
    stepOf(2, 'Orders', ''),
    stepOf(3, null, ''),
    stepOf(4, 'Web', 'Shows it.'),
  ],
};

describe('targetFlowDiagram', () => {
  it('RF-625 draws the trigger as an actor with a note, then every step in order', () => {
    expect(targetFlowDiagram(flow, keep).split('\n')).toEqual([
      'sequenceDiagram',
      '  actor p1 as User',
      '  participant p2 as Web',
      '  participant p3 as Orders',
      '  Note over p1: The customer presses Pay.',
      '  p1->>p2: 1. Sends it.',
      '  p2->>p3: 2. Legacy step 2.',
      '  p3->>p3: 3. Legacy step 3. #40;not mapped#41;',
      '  p3->>p2: 4. Shows it.',
      '  Note over p2: Outcome#58; The order is stored.',
      '',
    ]);
  });

  it('RF-625 a step mapped to no component keeps its number and is marked on the nearest one', () => {
    const text = targetFlowDiagram(flow, keep);

    expect(text).toContain('3. Legacy step 3');
    expect(text).toContain('not mapped');
    expect(text.match(/not mapped/gu)).toHaveLength(1);
  });
});

describe('targetFlowDiagram: markers and actors', () => {
  it('RF-625 a step before the first mapped one is drawn on the next mapped component', () => {
    const text = targetFlowDiagram(
      { ...flow, steps: [stepOf(1, null, ''), stepOf(2, 'Web', '')] },
      keep,
    );

    expect(text).toContain('p1->>p2: 1. Legacy step 1. #40;not mapped#41;');
    expect(text).toContain('p2->>p2: 2. Legacy step 2.');
    expect(text).not.toContain('Legacy step as');
  });

  it('RF-625 a flow with no mapped step draws every step on a Legacy step participant', () => {
    const text = targetFlowDiagram(
      { ...flow, steps: [stepOf(1, null, ''), stepOf(2, null, '')] },
      keep,
    );

    expect(text).toContain('participant p2 as Legacy step');
    expect(text.match(/not mapped/gu)).toHaveLength(2);
  });
});

describe('targetFlowDiagram: inferred steps', () => {
  it('RF-625 a step placed by the code, not the planner, is marked inferred', () => {
    const inferred = { ...stepOf(1, 'Web', ''), inferred: true };
    const text = targetFlowDiagram({ ...flow, steps: [inferred] }, keep);

    expect(text).toContain('1. Legacy step 1. #40;inferred#41;');
    expect(text).not.toContain('not mapped');
  });

  it('RF-625 a flow whose every step is mapped carries no marker', () => {
    const mapped = { ...flow, steps: flow.steps.map((step) => ({ ...step, component: 'Web' })) };

    expect(targetFlowDiagram(mapped, keep)).not.toContain('not mapped');
  });

  it('RF-625 names the actor for who starts the flow and keeps it short', () => {
    expect(triggerActor('An HTTP request arrives at the web host.')).toBe('Client');
    expect(triggerActor('A nightly job runs.')).toBe('Scheduler');
    expect(triggerActor('The customer presses Pay.')).toBe('User');
    expect(triggerActor('Something odd happens.')).toBe('Trigger');
    expect(triggerActor('x'.repeat(500)).length).toBeLessThanOrEqual(40);
  });

  it('RF-625 no trigger is stated: an actor and no trigger note', () => {
    const text = targetFlowDiagram({ ...flow, trigger: '', outcome: '' }, keep);

    expect(text).toContain('actor p1 as Trigger');
    expect(text).not.toContain('Note over');
  });
});

describe('targetFlowDiagram: names and secrets', () => {
  it('RF-508 a component named like the trigger is a participant of its own', () => {
    const text = targetFlowDiagram(
      { ...flow, trigger: 'Web', steps: flow.steps.slice(0, 1) },
      keep,
    );

    expect(text.match(/participant|actor/gu)).toHaveLength(2);
  });

  it('RF-508 hostile names, actions and texts cannot add a statement, a link or HTML', () => {
    const hostile =
      'x"\n  Note over p1: injected;%% {init} <img src=x onerror=1> click p1 call evil() direction TB';

    const text = targetFlowDiagram(mappedFlow(hostile), keep);

    const lines = text.split('\n').filter((line) => line !== '');
    expect(lines[0]).toBe('sequenceDiagram');
    expect(lines).toHaveLength(1 + 2 + 1 + 2 + 1);
    expect(text).not.toMatch(/[<"`%{}]|direction|injected;/u);
    const shape = /^ {2}((?:participant|actor) p\d+ as |p\d+->>p\d+: |Note over p\d+: )/u;
    expect(lines.slice(1).every((line) => shape.test(line))).toBe(true);
  });

  it('RNF-003 masks a secret before a label is coded', () => {
    const mask = (text: string): string => text.replaceAll(fakeOpenAiKey, 'MASKED');

    const text = targetFlowDiagram(mappedFlow(`key ${fakeOpenAiKey}`), mask);

    expect(text).not.toContain(fakeOpenAiKey.slice(8, 30));
    expect(text).toContain('MASKED');
  });
});
